const WHITELIST = ['5591982250731']; // [] = responde a todos os contatos diretos
const EVOLUTION = 'http://evolution-api:8080';
const EVO_KEY = '7539443e08ab02320e9afd7d9b2149c9';
const INSTANCE = 'principal';
const CRM = 'http://sansol-crm:3000';
const WA_TOKEN = '45d0608818ca6462b540e615fc0b6f1ade82db2045b4d1dc';
const OLLAMA = 'http://host.docker.internal:11434';
const MODEL = 'llama3.1:8b';
const H_JSON = { 'Content-Type': 'application/json' };
const H_CRM = { 'Content-Type': 'application/json', 'x-webhook-token': WA_TOKEN };
const H_EVO = { 'Content-Type': 'application/json', apikey: EVO_KEY };

const http = async (o) => this.helpers.httpRequest(o);

const body = $input.first().json.body ?? $input.first().json;
const data = body.data ?? {};
const key = data.key ?? {};

// Filtros de seguranca
if (body.event !== 'messages.upsert') return [];
if (key.fromMe) return [];
const remoteJid = String(key.remoteJid || '');
if (!remoteJid.endsWith('@s.whatsapp.net')) return []; // ignora grupos, status, broadcast, canais
const phone = remoteJid.replace(/@.*/, '');
if (WHITELIST.length && !WHITELIST.includes(phone)) return [];
const name = data.pushName || phone;

// Texto ou audio
let text = data.message?.conversation ?? data.message?.extendedTextMessage?.text ?? '';
let mediaType = 'text';
const audio = data.message?.audioMessage;
if (!text && audio) {
  mediaType = 'audio';
  try {
    const media = await http({ method: 'POST', url: EVOLUTION + '/chat/getBase64FromMediaMessage/' + INSTANCE, headers: H_EVO, body: { message: data } });
    const b64 = media.base64 || media?.data?.base64;
    const buf = Buffer.from(b64, 'base64');
    const trans = await this.helpers.request({ method: 'POST', url: 'http://whisper:9000/asr?task=transcribe&language=pt&output=json', formData: { audio_file: { value: buf, options: { filename: 'audio.ogg', contentType: media.mimetype || 'audio/ogg' } } } });
    const parsed = typeof trans === 'string' ? JSON.parse(trans) : trans;
    text = String(parsed.text || '').trim();
  } catch (e) {
    // Nao conseguiu transcrever: pede por escrito e encerra.
    await http({ method: 'POST', url: EVOLUTION + '/message/sendText/' + INSTANCE, headers: H_EVO, body: { number: phone, text: 'Oi! Recebi seu áudio, mas não consegui ouvir direito por aqui 😅 Pode me mandar por mensagem escrita?' } });
    return [{ json: { phone, error: 'audio_failed', detail: String(e.message || e) } }];
  }
}
if (!text) return [];

// Registra a mensagem no CRM e pega o estado da conversa
const inbound = await http({ method: 'POST', url: CRM + '/api/wa/inbound', headers: H_CRM, body: { phone, name, text, mediaType, providerMessageId: key.id } });
const conversationId = inbound.conversationId;
let botStatus = inbound.botStatus;
const history = inbound.history || [];

// Retomar atendimento automatico
const resume = /(atendimento autom|voltar ao rob|reativar (o )?bot|ativar (o )?rob|menu inicial)/i.test(text);
if (botStatus === 'human' && !resume) {
  return [{ json: { phone, conversationId, skipped: 'atendimento humano ativo' } }];
}
if (resume && botStatus === 'human') {
  await http({ method: 'POST', url: CRM + '/api/wa/handoff', headers: H_CRM, body: { conversationId, mode: 'auto' } });
  botStatus = 'auto';
}

// Gera a resposta com o Ollama (JSON estruturado)
const system = 'Você é a Sol, atendente virtual da Sansol Energia Solar (Santa Catarina, Brasil). Fale como uma pessoa de verdade: simpática, calorosa, com linguagem simples e acessível, sem jargão técnico. Ajude o cliente com energia solar e, com naturalidade (sem parecer interrogatório), descubra a cidade dele e o valor médio da conta de luz. Nunca invente preços fechados: diga que um consultor prepara a proposta. No máximo 3 frases curtas. Se o cliente pedir para falar com um atendente/humano/pessoa, marque wants_human=true. Responda SOMENTE com o JSON pedido.';
const schema = { type: 'object', properties: { reply: { type: 'string' }, wants_human: { type: 'boolean' }, qualified: { type: 'boolean' }, city: { type: ['string', 'null'] }, bill: { type: ['string', 'null'] } }, required: ['reply', 'wants_human', 'qualified'] };
const messages = [{ role: 'system', content: system }];
for (const m of history) messages.push({ role: m.direction === 'in' ? 'user' : 'assistant', content: m.body });

let out;
try {
  const ai = await http({ method: 'POST', url: OLLAMA + '/api/chat', headers: H_JSON, body: { model: MODEL, stream: false, format: schema, options: { temperature: 0.4 }, messages } });
  out = JSON.parse(ai.message.content);
} catch (e) {
  out = { reply: 'Oi! Sou a Sol, da Sansol Energia Solar 🌞 Como posso te ajudar hoje?', wants_human: false, qualified: false };
}

let reply = String(out.reply || '').trim();
if (out.wants_human) {
  await http({ method: 'POST', url: CRM + '/api/wa/handoff', headers: H_CRM, body: { conversationId, mode: 'human' } });
  reply = 'Claro! Vou chamar um consultor da nossa equipe pra te atender por aqui. Só um instante 🙌 (Quando quiser voltar a falar comigo, é só escrever "atendimento automático".)';
}
if (!reply) reply = 'Pode me contar um pouco mais? 😊';

// Envia pelo WhatsApp
const sent = await http({ method: 'POST', url: EVOLUTION + '/message/sendText/' + INSTANCE, headers: H_EVO, body: { number: phone, text: reply } });
const providerMessageId = sent?.key?.id;

// Registra a resposta e salva/atualiza o contato no CRM
await http({ method: 'POST', url: CRM + '/api/wa/outbound', headers: H_CRM, body: { conversationId, text: reply, providerMessageId } });
if (!out.wants_human) {
  await http({ method: 'POST', url: CRM + '/api/contacts', headers: H_CRM, body: { phone, name, city: out.city || null, bill: out.bill || null, qualified: !!out.qualified } });
}

return [{ json: { phone, conversationId, reply, botStatus, wants_human: !!out.wants_human, qualified: !!out.qualified } }];
